namespace sv_098099d9fb9d41f2a9e2e36620266164.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

namespace sv_098099d9fb9d41f2a9e2e36620266164.Services;

/// <summary>
/// Scoped service (one instance per circuit) that holds the current theme
/// state and notifies all subscribers when it changes.
/// </summary>
public class ThemeService
{
    private readonly ThemeInfo _current = new();

    public Theme Theme => _current.Theme;
    public string AccentColor => _current.AccentColor;

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (_current.Theme == theme) return;
        _current.Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (_current.AccentColor == color) return;
        _current.AccentColor = color;
        OnChange?.Invoke();
    }
}

