@* Rendered as InteractiveServer so it can re-render when the scoped
   ThemeService fires OnChange — even though the MainLayout is static. *@
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="badge rounded-pill"
      style="background-color: @ThemeSvc.AccentColor; color: white;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>User Preferences</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <button class="btn @(ThemeSvc.Theme == t ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.SetTheme(t)">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <input type="color"
               class="form-control form-control-color mb-3"
               value="@ThemeSvc.AccentColor"
               @onchange="OnAccentChanged" />

        <p class="text-muted mb-0">
            Current: <strong>@ThemeSvc.Theme</strong> &middot;
            <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    private void OnAccentChanged(ChangeEventArgs e)
        => ThemeSvc.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

